solution.Solution.cs:
public static class Sales
{
    public static List<(string Name, decimal Total)> Totals(IEnumerable<Customer> customers, IEnumerable<Order> orders)
        => customers
            .GroupJoin(orders, c => c.Id, o => o.CustomerId, (c, os) => (c.Name, Total: os.Sum(o => o.Total)))
            .OrderByDescending(t => t.Total)
            .ThenBy(t => t.Name, StringComparer.Ordinal)
            .ToList();
}

unitTests:
var customers = new List<Customer> { new(1, "Cy"), new(2, "Ada"), new(3, "Bob"), new(4, "Dee") };
var orders = new List<Order> { new(10, 2, 30m), new(11, 3, 20m), new(12, 2, 15m), new(13, 3, 25m) };

Test("sums per customer, highest first, ties by name", () =>
{
    var t = Sales.Totals(customers, orders);
    CheckEq(string.Join(";", t.Select(x => $"{x.Name}={x.Total}")), "Ada=45;Bob=45;Cy=0;Dee=0");
});

Test("no orders at all", () =>
{
    CheckEq(Sales.Totals(customers, new List<Order>()).Count, 4);
});

Test("no customers", () =>
{
    CheckEq(Sales.Totals(new List<Customer>(), orders).Count, 0);
});

